-- 027: public rate range from the private estimate, origin corrections, and links from the DJ research files. Fill-only where empty.
update public.artists a set
  fee_min_inr = replace((regexp_match(p.fee_text, '^₹([0-9,]+)'))[1], ',', '')::numeric,
  fee_max_inr = replace(coalesce((regexp_match(p.fee_text, '–₹([0-9,]+)'))[1], (regexp_match(p.fee_text, '^₹([0-9,]+)'))[1]), ',', '')::numeric,
  fee_currency = 'INR'
from public.private_contacts p
where p.kind = 'artist' and p.slug = a.slug and p.fee_text ~ '^₹[0-9,]+' and a.fee_min_inr is null;
